using System;using System.IO;using System.Linq;using HdrPilot;
class ModTests {
 static int n;static void Check(bool value,string message){if(!value)throw new Exception(message);Console.WriteLine("PASS "+message);n++;}static void Reject(Action a,string m){bool failed=false;try{a();}catch{failed=true;}Check(failed,m);}
 static int Main(string[] a){try{string root=Path.GetFullPath(a[0]);Directory.CreateDirectory(root);Core.Data=Path.Combine(root,"data");Core.Init();var dir=Path.Combine(root,"game");Directory.CreateDirectory(dir);var g=new Game{Id="mods-fixture",Name="Fixture",Root=dir,Exe=Path.Combine(dir,"Game.exe")};File.Copy(typeof(Core).Assembly.Location,g.Exe);string dll=AsiLoader.Extract(Path.GetFullPath(a[1]));Check(AsiLoader.IsLoader(dll),"official ASI x64 extraction");var p=AsiLoader.Prepare(g,dll,"dinput8.dll");DlssCore.Apply(g,p);Check(AsiLoader.Installed(g).SequenceEqual(new[]{"dinput8.dll"}),"ASI installed and detected");Reject(()=>AsiLoader.Prepare(g,dll,"winmm.dll"),"identical existing ASI is no-op");DlssCore.Apply(g,AsiLoader.Restore(g));Check(AsiLoader.Installed(g).Length==0,"ASI original absence restored");File.WriteAllText(Path.Combine(dir,"version.dll"),"other loader");Reject(()=>AsiLoader.Prepare(g,dll,"version.dll"),"occupied name preserved");File.Copy(dll,Path.Combine(dir,"winmm.dll"));File.Copy(dll,Path.Combine(dir,"dinput8.dll"));Reject(()=>AsiLoader.Prepare(g,dll,"version.dll"),"duplicate ASI blocked");File.Delete(Path.Combine(dir,"winmm.dll"));File.Delete(Path.Combine(dir,"dinput8.dll"));p=AsiLoader.Prepare(g,dll,"dinput8.dll");File.WriteAllText(Path.Combine(dir,"dinput8.dll"),"race");Reject(()=>DlssCore.Apply(g,p),"ASI target race blocked");File.Delete(Path.Combine(dir,"dinput8.dll"));
 File.Copy(Path.GetFullPath(a[2]),Path.Combine(dir,"ReShade64.dll"));File.WriteAllText(Path.Combine(dir,"OptiScaler.ini"),"[Plugins]\nLoadReshade=true\n");File.Copy(g.Exe,Path.Combine(dir,"renodx-fixture.addon64"));File.Copy(g.Exe,Path.Combine(dir,"renodx-mfgunlock.addon64"));File.WriteAllText(Path.Combine(dir,"ReShade.ini"),"[ADDON]\nLoadFromDllMain=renodx-mfgunlock.addon64\n");File.WriteAllText(Path.Combine(dir,"nvngx_dlss.dll"),"native");File.WriteAllText(Path.Combine(dir,"sl.common.dll"),"streamline");File.WriteAllText(Path.Combine(dir,"example.asi"),"mod");Check(ModRemoval.Linked(g),"ReShade dependency detected");Reject(()=>ModRemoval.Prepare(g,false,false,true),"dependent ReShade cannot be stranded");p=ModRemoval.Prepare(g,false,true,false);Check(p.Changes.All(x=>x.Name=="renodx-fixture.addon64"),"RenoDX-only preserves MFG and ReShade");p=ModRemoval.Prepare(g,true,true,true);Check(p.Changes.Select(x=>x.Name).Distinct(StringComparer.OrdinalIgnoreCase).Count()==p.Changes.Count,"combined removal has no duplicate changes");Check(p.Changes.Any(x=>x.Name=="renodx-mfgunlock.addon64"&&x.Delete),"MFG included with ReShade");string recovery=DlssCore.Apply(g,p);Check(!File.Exists(Path.Combine(dir,"ReShade64.dll"))&&!File.Exists(Path.Combine(dir,"OptiScaler.ini")),"combined removal applied");Check(File.ReadAllText(Path.Combine(dir,"nvngx_dlss.dll"))=="native"&&File.ReadAllText(Path.Combine(dir,"sl.common.dll"))=="streamline"&&File.Exists(Path.Combine(dir,"example.asi")),"native components and ASI preserved");DlssCore.Apply(g,DlssCore.Recovery(g,Path.Combine(recovery,"transaction.json")));Check(File.Exists(Path.Combine(dir,"ReShade64.dll"))&&File.Exists(Path.Combine(dir,"renodx-mfgunlock.addon64")),"combined recovery restores files");Directory.CreateDirectory(Path.Combine(dir,"addons"));File.Move(Path.Combine(dir,"renodx-fixture.addon64"),Path.Combine(dir,"addons","renodx-fixture.addon64"));File.WriteAllText(Path.Combine(dir,"ReShade.ini"),"[ADDON]\nAddonPath=addons\n");p=ModRemoval.Prepare(g,false,true,false);Check(p.Changes.Any(x=>x.Name.Replace('\\','/').Equals("addons/renodx-fixture.addon64")),"custom HDR add-on folder detected");p=ModRemoval.Prepare(g,true,true,false);Check(p.Changes.Any(x=>x.Name==MfgAddon.Name&&x.Delete),"root MFG residue removed with custom path");Console.WriteLine("PASS "+n+" mod checks");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
